def slugify(s):
    # Lowercase, then decompose and strip any accent marks (e.g. õ -> o)
    s = unicodedata.normalize('NFD', s.lower())
    s = ''.join(ch for ch in s if not unicodedata.combining(ch))
    # Replace every non-alphanumeric character with a hyphen, then
    # collapse consecutive hyphens into one
    s = '-'.join(
        part
        for part in (
            ch if ch.isalnum() else '-' for ch in s
        )
        if part
    )
    # Collapse runs of hyphens into a single hyphen
    while '--' in s:
        s = s.replace('--', '-')
    return s.strip('-')

import unicodedata


def slugify(s):
    # Lowercase, then decompose and strip any accent marks (e.g. õ -> o)
    s = unicodedata.normalize('NFD', s.lower())
    s = ''.join(ch for ch in s if not unicodedata.combining(ch))

    # Map every non-alphanumeric character to a hyphen, keeping at most one
    # hyphen per run of separators
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        elif not out or out[-1] != '-':
            out.append('-')
    return ''.join(out).strip('-')

